function interpolate(value, variables = {}) {
  return value.replace(/\{(\w+)\}/g, (match, key) => Object.prototype.hasOwnProperty.call(variables, key) ? variables[key] : match);
}

export function getInitialLanguage() {
  const stored = window.localStorage.getItem(LANGUAGE_KEY);
  if (stored === 'en' || stored === 'zh') return stored;
  return navigator.language?.toLowerCase().startsWith('en') ? 'en' : 'zh';
}

export function setStoredLanguage(language) {
  window.localStorage.setItem(LANGUAGE_KEY, language);
  document.documentElement.lang = language === 'en' ? 'en' : 'zh-CN';
}

export function translate(language, key, variables) {
  const value = messages[language]?.[key] || messages.zh[key] || key;
  return interpolate(value, variables);
}

export function localizedModel(model, language) {
  return { ...model, description: translate(language, model.descriptionKey) };
}

export function localizedPlan(plan, language) {
  return { ...plan, name: translate(language, plan.nameKey), description: translate(language, plan.descriptionKey), tag: translate(language, plan.tagKey) };
}

export { messages };
